--
-- Cấu trúc bảng cho bảng `locations`
--

CREATE TABLE `locations` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED NOT NULL,
  `district_id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `address` varchar(255) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `facebook_url` varchar(255) DEFAULT NULL,
  `zalo_url` varchar(255) DEFAULT NULL,
  `lat` decimal(10,8) DEFAULT NULL,
  `lng` decimal(11,8) DEFAULT NULL,
  `min_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `max_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `opening_time` time DEFAULT NULL,
  `closing_time` time DEFAULT NULL,
  `featured_image` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `type` varchar(100) DEFAULT NULL,
  `google_map_url` text DEFAULT NULL,
  `view_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `status` varchar(20) DEFAULT 'approved',
  `submitted_by` varchar(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Đang đổ dữ liệu cho bảng `locations`
--

INSERT INTO `locations` (`id`, `category_id`, `district_id`, `name`, `slug`, `address`, `phone`, `facebook_url`, `zalo_url`, `lat`, `lng`, `min_price`, `max_price`, `opening_time`, `closing_time`, `featured_image`, `description`, `type`, `google_map_url`, `view_count`, `created_at`, `updated_at`, `status`, `submitted_by`) VALUES
(1, 1, 38, 'Ẩm thực Cầu Tre - Trà Vinh', 'm-th-c-c-u-tre-tr-vinh', 'Liền kề ký túc xá, K4/D5 nối dài, Phường Hòa Thuận, Trà Vinh', '(0270) 000 0000', '', '', 9.91870890, 106.34915150, 100000.00, 300000.00, '09:00:00', '23:00:00', '/images/Dichvu/Am thuc/amthuc1.webp', 'Ẩm thực CẦU TRE là một tụ điểm ăn uống mang phong cách đồng quê nổi tiếng, rất được giới trẻ và gia đình ưa chuộng tại Trà Vinh. Nơi đây nổi bật với không gian mát mẻ bên bờ kênh cùng hệ thống nhà chòi riêng tư, vừa lãng mạn vừa thoải mái – lựa chọn quen thuộc cho các buổi liên hoan, họp mặt gia đình, gặp gỡ bạn bè hay hẹn hò. Đặc biệt, không gian thoáng đãng giúp thực khách vừa thưởng thức món ăn vừa ngắm cảnh thiên nhiên sông nước miền Tây đầy thơ mộng.\n\nThực đơn đa dạng gồm các món gà nướng cơm lam, lẩu hải sản, gỏi bông bần và nhiều món ăn đặc trưng khác. Nổi bật là những món nướng thơm lừng kết hợp với rau sống và nước chấm đậm đà. Nhà hàng còn có khu vực dành riêng cho nhóm đông người, rất thích hợp tổ chức tiệc sinh nhật hoặc gặp gỡ công ty. Giá cả ở mức trung bình (100.000 – 300.000đ/người), dịch vụ ân cần và tốc độ phục vụ nhanh chóng. Nhà hàng mở cửa từ 9h sáng đến 23h tối, cả tuần lẫn cuối tuần. Bãi đậu xe rộng rãi, thuận tiện di chuyển cả ô tô lẫn xe máy. Với chất lượng món ăn tươi ngon cùng bầu không khí gần gũi, Ẩm thực Cầu Tre là lựa chọn hàng đầu cho ai muốn trải nghiệm không gian \"chill\" nhưng vẫn đậm chất truyền thống.', 'Nhà hàng', 'https://www.google.com/maps/place/%E1%BA%A8m+th%E1%BB%B1c+C%E1%BA%A7u+Tre+-+Tr%C3%A0+Vinh/@9.9187142,106.3465766,17z/data=!3m1!4b1!4m6!3m5!1s0x31a0114616ce6459:0xbdfffd5d07a3d2cc!8m2!3d9.9187089!4d106.3491515!16s%2Fg%2F11fkt7bf5t', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(2, 1, 38, 'Mì cay Yagami Ẩm thực Thái - Nhật - Hàn', 'm-cay-yagami-m-th-c-th-i-nh-t-h-n', 'W8FX+GMC, Hòa Thuận, Trà Vinh', '(0270) 000 0000', '', '', 9.91871420, 106.34657660, 50000.00, 150000.00, '10:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc2.jpg', 'Mì Cay Yagami là thương hiệu ẩm thực Thái – Nhật – Hàn hàng đầu tại Việt Nam với hơn 10 năm kinh nghiệm trong ngành F&B. Sau 10 năm phát triển cùng hệ thống hơn 190 chi nhánh trải dài khắp miền Nam, từ Đồng Nai, Bình Dương, TP. Hồ Chí Minh cho đến Vĩnh Long, Mì Cay Yagami đã trở thành điểm đến quen thuộc của hàng triệu thực khách yêu thích hương vị Châu Á.\n\nMì Cay Yagami mang đến thực đơn phong phú với các món đặc trưng như Mì Cay Hàn Quốc đủ cấp độ cay theo yêu cầu, Lẩu Thái chua chua cay cay đậm đà, Sushi Nhật Bản tươi ngon, cùng hàng chục món ăn đa dạng từ ba nền ẩm thực nổi tiếng. Món ăn được chế biến từ nguyên liệu tươi mới mỗi ngày, đảm bảo chất lượng và an toàn vệ sinh thực phẩm. Không gian nhà hàng hiện đại, trẻ trung, phù hợp với giới trẻ và gia đình đi nhóm. Mức giá bình dân (50.000 – 150.000đ/người) phù hợp túi tiền học sinh, sinh viên cũng như người đi làm. Quán mở cửa từ 10h sáng đến 10h tối, có hỗ trợ giao hàng tận nơi và đặt bàn trước qua điện thoại. Bãi giữ xe an toàn, rộng rãi. Với hương vị độc đáo cùng phong cách phục vụ chuyên nghiệp, Mì Cay Yagami là điểm đến lý tưởng cho mọi bữa tiệc nhỏ, gặp gỡ bạn bè hoặc đơn giản là thỏa mãn cơn thèm đồ ăn Á Đông.', 'Quán ăn', NULL, 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(3, 1, 38, 'Quán Nhà Lá', 'qu-n-nh-l', 'Đường D5, QL53, Hòa Thuận, Trà Vinh', '(0270) 000 0000', '', '', 9.92713350, 106.34802860, 100000.00, 250000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc3.jpg', 'Ẩm Thực Gia Đình Nhà Lá – Nơi Những Bữa Ăn Trở Thành Ký Ức. Được xây dựng theo phong cách nhà vườn truyền thống với mái lá, cây xanh rợp bóng, Nhà Lá mang đến không gian ăn uống gần gũi thiên nhiên, mát mẻ và yên tĩnh giữa lòng thành phố Vĩnh Long. Nhà hàng có thiết kế mở, thoáng đãng, đầy gió và ánh sáng tự nhiên, rất thích hợp cho các buổi tụ họp gia đình hoặc tiệc liên hoan bạn bè. Mỗi khu vực ngồi được bố trí hài hòa, vừa mang lại sự riêng tư vừa gần gũi, tạo cảm giác thân thuộc như đang về thăm quê.\n\nThực đơn của Nhà Lá tập trung vào các món hải sản tươi sống, canh chua cá, lẩu các loại và đặc biệt là những món ăn gia đình đậm đà hương vị miền Tây. Nguyên liệu được chọn lọc kỹ càng, chế biến theo công thức truyền thống giữ trọn vị ngon tự nhiên. Giá cả hợp lý (100.000 – 250.000đ/người), phù hợp với nhiều đối tượng thực khách từ sinh viên đến gia đình. Nhà hàng mở cửa từ 8h sáng đến 10h tối hằng ngày, phục vụ cả bữa sáng, trưa và tối. Bãi đậu xe rộng, đội ngũ nhân viên nhiệt tình và chu đáo. Với không gian xanh mát cùng hương vị món ăn gia đình đậm đà, Nhà Lá là điểm đến lý tưởng cho những ai yêu thích sự bình dị, chân thật và muốn tận hưởng bữa ăn ngon giữa thiên nhiên.', 'Nhà hàng', 'https://www.google.com/maps/place/Qu%C3%A1n+Nh%C3%A0+L%C3%A1/@10.0198017,106.1346637,11z/data=!4m10!1m2!2m1!1zUXXDoW4gTmjDoCBMw6E!3m6!1s0x31a0175c0b71a1ed:0xc386685923289a68!8m2!3d9.9271335!4d106.3480286', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(4, 1, 38, 'NHÀ HÀNG LÀNG BÈ', 'nh-h-ng-l-ng-b', '6b ấp Mỹ An, Phú Túc, Trà Vinh', '(0270) 000 0000', '', '', 10.32744500, 106.35147930, 50000.00, 200000.00, '08:00:00', '20:00:00', '/images/Dichvu/Am thuc/amthuc4.jpg', 'Khu du lịch Làng Bè là điểm đến sinh thái hấp dẫn tại Vĩnh Long, mang đến cho du khách không gian miệt vườn sông nước yên bình đậm chất Tây Nam Bộ. Khu vui chơi có diện tích rộng với nhiều hoạt động trải nghiệm dân gian như chèo xuồng ba lá, câu cá giải trí, thăm vườn trái cây, hay thưởng thức ca nhạc dân ca, đờn ca tài tử. Đặc biệt, nhà hàng trong khu du lịch phục vụ các món ăn đặc sản miền Tây vô cùng phong phú như cá lóc nướng trui, lẩu cá, gỏi củ hủ dừa, cá tai tượng chiên xù, và nhiều món chế biến từ cá bè tươi sống nuôi ngay tại chỗ.\n\nKhông gian ăn uống tại Làng Bè rất thoáng mát, các khu vực bàn ăn nằm sát bên dòng sông, được bao quanh bởi cây xanh và bóng mát tự nhiên, tạo cảm giác thư giãn tuyệt vời. Giá cả bình dân (50.000 – 200.000đ/người), phù hợp cho gia đình và nhóm bạn đi du lịch cuối tuần. Khu du lịch mở cửa từ 8h sáng đến 8h tối, có bãi đậu xe rộng rãi, khu vực vệ sinh sạch sẽ và dịch vụ chu đáo. Đây là lựa chọn lý tưởng cho những chuyến đi kết hợp vui chơi giải trí và thưởng thức ẩm thực đồng quê ngon khó cưỡng. Làng Bè không chỉ là điểm đến ăn uống mà còn là trải nghiệm văn hóa miệt vườn sống động và đáng nhớ.', 'Nhà hàng', 'https://www.google.com/maps/place/NH%C3%80+H%C3%80NG+L%C3%80NG+B%C3%88/@10.3274503,106.3489044,17z/data=!3m1!4b1!4m6!3m5!1s0x310aaf7f2375ef5b:0x4081ab8db7859ec7!8m2!3d10.327445!4d106.3514793', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(5, 1, 38, 'Nhà hàng Sông Nước Miền Tây', 'nh-h-ng-s-ng-n-c-mi-n-t-y', '52-53/18 Ấp 3, Phú Túc, Trà Vinh', '(0270) 000 0000', '', '', 10.33142710, 106.37755850, 100000.00, 350000.00, '07:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc5.jpg', 'Nhà hàng Sông Nước Miền Tây là điểm đến lý tưởng để thưởng thức ẩm thực đồng quê đặc trưng của vùng Tây Nam Bộ. Nổi bật với không gian miệt vườn mát mẻ, nhà hàng mang đến trải nghiệm ẩm thực đậm chất sông nước hữu tình, bao quanh bởi cây xanh, ao cá và không khí trong lành. Đặc biệt, khu vực bàn ăn được bố trí sát bờ sông giúp thực khách vừa thưởng thức món ăn vừa thư giãn giữa thiên nhiên.\n\nThực đơn của Nhà hàng Sông Nước Miền Tây rất phong phú với các đặc sản nổi tiếng như cá lóc nướng trui thơm phức, lẩu mắm đậm đà hương vị đồng quê, gỏi củ hủ dừa giòn ngọt, cùng nhiều món chế biến từ hải sản tươi sống và thịt gia súc được nuôi tại địa phương. Mỗi món đều mang hương vị dân dã nhưng tinh tế, phản ánh chân thực ẩm thực sông nước miền Tây. Giá cả từ 100.000 – 350.000đ/người tùy món, phù hợp cho nhiều đối tượng thực khách từ gia đình, nhóm bạn đến các đoàn du lịch. Nhà hàng mở cửa từ 7h sáng đến 10h tối hằng ngày, phục vụ suốt cả tuần. Không gian rộng rãi, bãi đậu xe thuận tiện, phục vụ nhanh chóng và nhiệt tình. Với bầu không khí thân thiện cùng món ăn thơm ngon đậm đà, Sông Nước Miền Tây là điểm dừng chân lý tưởng cho chuyến du lịch khám phá Vĩnh Long.', 'Nhà hàng', 'https://www.google.com/maps/place/Nh%C3%A0+h%C3%A0ng+S%C3%B4ng+N%C6%B0%E1%BB%9Bc+Mi%E1%BB%81n+T%C3%A2y/@10.3314324,106.3749836,17z/data=!3m1!4b1!4m6!3m5!1s0x310aafa6e7676f63:0xfc533eddf142df99!8m2!3d10.3314271!4d106.3775585', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(6, 1, 40, 'Ất Sửu Quán (Bò Nướng Ngói)', 't-s-u-qu-n-b-n-ng-ng-i', 'Bờ kè Cách Mạng Tháng 8, Trà Cú, Trà Vinh', '(0270) 000 0000', '', '', 9.69019030, 106.25733620, 150000.00, 300000.00, '10:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc6.jpg', 'Ất Sửu Quán tại Trà Vinh là điểm đến nổi bật với món đặc sản Bò Nướng Ngói trứ danh, thu hút đông đảo thực khách gần xa ghé thăm. Điểm nhấn của quán chính là phong cách thưởng thức độc đáo: thực khách sẽ được tự tay nướng những lát thịt bò tươi ngon trên tấm ngói nung nóng đỏ, giúp giữ trọn độ ngọt tự nhiên, độ mềm dai vừa phải của thịt bò. Khi ăn kèm với rau sống, bánh tráng và nước chấm đặc biệt, món ăn trở nên vô cùng hấp dẫn và khó quên.\n\nKhông gian quán thoáng mát, nằm ven bờ kè Cách Mạng Tháng 8, view nhìn ra sông rất đẹp vào buổi chiều tối. Ngoài món bò nướng ngói, thực đơn còn có bò cuốn lá lốt, bò tái chanh, bò nhúng dấm và nhiều món ăn khác đều được chế biến cầu kỳ và tinh tế. Giá cả từ 150.000 – 300.000đ/người, phù hợp cho buổi tụ tập bạn bè hoặc tiệc gia đình. Quán mở cửa từ 10h sáng đến 10h tối, phục vụ liên tục cả tuần. Không gian sạch sẽ, bàn ghế ngăn nắp, phục vụ nhiệt tình. Bãi đậu xe rộng, thuận tiện cho khách đi ô tô. Với chất lượng món ăn xuất sắc cùng trải nghiệm nướng ngói độc đáo, Ất Sửu Quán là lựa chọn hàng đầu cho những ai yêu thích thịt bò và muốn thử một phong cách ẩm thực mới mẻ ở Trà Vinh.', 'Nhà hàng', 'https://www.google.com/maps/place/%E1%BA%A4t+S%E1%BB%ADu+Qu%C3%A1n+(B%C3%B2+N%C6%B0%E1%BB%9Bng+Ng%C3%B3i)/@9.6901903,106.1049009,12z/data=!4m11!1m3!2m2!1zbmjDoCBow6BuZyB2xKluaCBsb25nIGPFqQ!6e5!3m6!1s0x31a03bc995c8f4c5:0xadcb50bfd6a6d04e!8m2!3d9.6901903!4d106.2573362', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(10, 1, 38, 'Hải sản Lưu Luyến', 'h-i-s-n-l-u-luy-n', 'W8QJ+695, Võ Văn Kiệt, Nguyệt Hóa, Trà Vinh', '02943844779', '', '', 9.93801250, 106.33096930, 80000.00, 300000.00, '08:00:00', '23:00:00', '/images/Dichvu/Am thuc/amthuc7.jpg', 'Quán Hải sản Lưu Luyến là một điểm hẹn ẩm thực nổi tiếng và được yêu thích tại thành phố Trà Vinh. Quán nổi tiếng với không gian rộng rãi, thoáng mát, cực kỳ lý tưởng để thưởng thức hải sản tươi sống và các món ăn đặc sản miền sông nước.\n Điểm nổi bật \nKhông gian & Thiết kế: Quán sở hữu không gian rộng rãi, sạch sẽ và thoáng đãng, tạo cảm giác thư giãn cho thực khách khi tụ tập cùng bạn bè hoặc gia đình. \nẨm thực phong phú: Thực đơn của quán rất đa dạng, bao gồm:\nHải sản tươi sống: Chế biến đậm đà hương vị biển cả.\nĐặc sản Trà Vinh: Các món ăn bình dân, thanh nhẹ mang đậm dấu ấn miền sông nước. \nDịch vụ & Giá cả: Phục vụ nhiệt tình, không gian vệ sinh sạch sẽ với mức giá cả bình dân, phải chăng.', 'Nhà hàng', 'https://www.google.com/maps/place/H%E1%BA%A3i+s%E1%BA%A3n+L%C6%B0u+Luy%E1%BA%BFn/@9.9377212,106.3309129,14z/data=!4m6!3m5!1s0x31a0174cf8195a59:0xdcd081ec0ff7c761!8m2!3d9.9380125!4d106.3309693', 0, '2026-06-15 09:48:05', '2026-06-16 09:36:21', 'approved', NULL),
(11, 1, 38, 'Ẩm thực Thanh Nhàn', 'm-th-c-thanh-nh-n', '134 Đ. Đồng Khởi, Khóm 9, Trà Vinh', '', '', '', 9.91871420, 106.34657660, 50000.00, 200000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc8.jpg', 'Thanh Nhàn - Ẩm thực quán là một trong những địa điểm ẩm thực sân vườn nổi bật, rất thích hợp cho các buổi họp mặt gia đình, liên hoan hoặc tiệc tùng, gặp gỡ bạn bè.\n1. Không gian và Phong cách\nKhông gian sân vườn rộng rãi: Điểm cộng lớn nhất của quán là khuôn viên xanh mát, thoáng đãng với nhiều cây cối, mang lại cảm giác thư thái và gần gũi với thiên nhiên như một khu sinh thái thu nhỏ. Bố trí linh hoạt: Quán có các khu vực bàn ăn ngoài trời thoáng mát để tận hưởng khí trời, đồng thời cũng có các khu vực chòi riêng tư hoặc không gian thích hợp cho các bữa tiệc gia đình, tiếp khách, họp nhóm.\n2. Ẩm thực và Thực đơn\nMón ăn đa dạng: Thực đơn của quán thiên về các món ăn gia đình, món nhậu bình dân cho đến các món hải sản, đặc sản đồng quê Nam Bộ. Các món ăn được chế biến đa dạng từ nướng, lẩu, hấp, xào... phù hợp với khẩu vị của đại đa số thực khách địa phương. Các món ăn tại quán thường được đánh giá cao nhờ khâu lựa chọn nguyên liệu tươi sống, cách nêm nếm đậm đà mang đậm chất miền Tây.\n3. Dịch vụ và Tiện ích\nPhục vụ nhiệt tình: Đội ngũ nhân viên thân thiện, nhanh nhẹn, đáp ứng tốt nhu cầu của các bàn tiệc đông người. Phù hợp đa dạng nhu cầu: Quán là điểm đến quen thuộc để tổ chức tiệc sinh nhật, liên hoan cuối năm, họp mặt bạn bè hay đơn giản là bữa cơm gia đình ấm cúng vào dịp cuối tuần.\n4. Thông tin liên hệ\nĐịa chỉ: Số 134 Đường Đồng Khởi, Khóm 9, Phường 6, Thành phố Trà Vinh (khu vực giáp ranh/tuyến quản lý thuế liên tỉnh). Giờ mở cửa: từ 08:00 đến 23:00 hằng ngày. Số điện thoại: 0388 722 069\nNếu bạn đang tìm kiếm một không gian ẩm thực rộng rãi, mát mẻ để thư giãn và thưởng thức các món ăn ngon cùng gia đình hay bạn bè, hãy chọn Thanh Nhàn - Ẩm thực quán!	', 'Quán ăn', 'https://www.google.com/maps/search/%E1%BA%A8m+th%E1%BB%B1c+Thanh+Nh%C3%A0n+/@9.9187142,106.3465766,17z', 0, '2026-06-15 09:48:06', '2026-06-16 09:36:21', 'approved', NULL),
(12, 1, 38, 'Ẩm Thực Ven Sông', 'm-th-c-ven-s-ng', '315 Phú Hòa, Long Đức, Trà Vinh', '0838780878', '', '', 9.95220670, 106.32134810, 50000.00, 200000.00, '09:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc9.jpg', 'Ẩm Thực Ven Sông tại Vĩnh Long là một địa điểm ăn uống lý tưởng dành cho những ai muốn tìm kiếm không gian ẩm thực sông nước mát mẻ, mang đậm phong cách miền Tây Nam Bộ.\nDưới đây là một số thông tin giới thiệu về quán:\nĐịa chỉ: 315 Phú Hòa, Long Đức, Thành phố Vĩnh Long, Vĩnh Long.\nThời gian mở cửa: 09:00 – 22:00 hàng ngày.\nSố điện thoại: +84 838 780 878\nĐúng như tên gọi, quán sở hữu vị trí đắc địa ngay ven sông, mang lại bầu không khí vô cùng thông thoáng, lộng gió và mát mẻ tự nhiên. Đây là nơi rất thích hợp cho các buổi họp mặt gia đình, tiệc sinh nhật, liên hoan, gặp gỡ bạn bè hoặc các đoàn khách du lịch muốn dừng chân nghỉ ngơi và thưởng thức đặc sản xứ sở sông nước.\nMenu của quán tập trung vào các món ăn dân dã, đậm đà hương vị đồng quê miền Tây, được chế biến từ nguồn nguyên liệu tươi sống:\nCác món cá sông, đặc sản đồng ruộng như cá lóc nướng, các món lẩu mắm, lẩu cua đồng.\nThực đơn đa dạng từ các món khai vị nhẹ nhàng, món xào, nướng cho đến hải sản và các món lẩu nóng hổi, phù hợp cho bữa cơm gia đình lẫn các buổi tiệc lai rai.', 'Nhà hàng', 'https://www.google.com/maps/place/%E1%BA%A8m+Th%E1%BB%B1c+Ven+S%C3%B4ng/@9.952212,106.3187732,17z/data=!3m1!4b1!4m6!3m5!1s0x31a011bde6bd5297:0x1a251ed8ac5fe0bb!8m2!3d9.9522067!4d106.3213481', 0, '2026-06-15 09:48:06', '2026-06-16 09:36:21', 'approved', NULL),
(13, 1, 39, 'Bò Tơ Giồng Trôm', 'b-t-gi-ng-tr-m', '131 Trương Vĩnh Trọng, Khu Phố 1, Giồng Trôm, Bến Tre', '0919208068', '', '', 10.15174580, 106.51582570, 100000.00, 200000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc10.jpg', 'Địa chỉ: Đường tỉnh 885, Ấp 5, Xã Bình Thành, Huyện Giồng Trôm, Tỉnh Bến Tre.\nThời gian mở cửa: Thường đón khách từ sáng đến tối muộn, phục vụ linh hoạt theo thời gian diễn ra sự kiện.\nNơi đây sở hữu diện tích rộng rãi, thoáng đãng với hai khu vực chính biệt lập nhưng bổ trợ cho nhau. Khu vực nhà hàng sân vườn mang phong cách bình dị, gần gũi với thiên nhiên, thích hợp cho các bữa ăn gia đình hay gặp gỡ bạn bè. Khu vực trung tâm hội nghị và tiệc cưới được đầu tư thiết kế hiện đại, sảnh tiệc rộng với sức chứa lớn, trang bị hệ thống âm thanh, ánh sáng và sân khấu chỉn chu để phục vụ cho các ngày vui trọng đại, lễ kỷ niệm hay hội nghị doanh nghiệp.\nThực đơn tại đây rất phong phú, trong đó điểm nhấn chính là các món ăn được chế biến từ bò tơ tươi ngon, chuẩn vị. Thịt bò được tuyển chọn kỹ lưỡng để đảm bảo độ mềm, ngọt tự nhiên, biến tấu thành nhiều món ăn hấp dẫn như bò tơ tơ lụi sả, bò nướng tảng, các món lẩu đuôi bò, lòng bò. Bên cạnh đặc sản bò tơ, nhà hàng còn phục vụ đa dạng các món ăn đậm chất đồng quê Nam Bộ và các thực đơn tiệc cưới phong phú từ bình dân đến cao cấp, đáp ứng khẩu vị của nhiều đối tượng khách hàng.\nVới lợi thế không gian rộng và bãi đỗ xe thoải mái, trung tâm cung cấp dịch vụ trọn gói từ khâu trang trí gia tiên, điều phối tiệc cưới, chuẩn bị thực đơn cho đến phục vụ. Đội ngũ nhân viên tại đây được đánh giá là nhiệt tình, nhanh nhẹn, góp phần mang lại sự chỉn chu cho các sự kiện quan trọng của người dân địa phương và các khu vực lân cận.', 'Nhà hàng', 'https://www.google.com/maps/place/B%C3%B2+T%C6%A1+Gi%E1%BB%93ng+Tr%C3%B4m+-+Trung+T%C3%A2m+H%E1%BB%99i+Ngh%E1%BB%8B,+S%E1%BB%B1+Ki%E1%BB%87n+Ti%E1%BB%87c+C%C6%B0%E1%BB%9Bi+Gi%E1%BB%93ng+Tr%C3%B4m/@10.1517511,106.5132508,17z', 0, '2026-06-15 09:48:06', '2026-06-16 09:36:21', 'approved', NULL),
(14, 1, 39, 'Mai Rừng Quán', 'mai-r-ng-qu-n', 'Đường Phó Cơ Điều, Phường 3, Thành phố Vĩnh Long', '0944944443', '', '', 10.04461800, 106.58469130, 50000.00, 300000.00, '08:00:00', '12:00:00', '/images/Dichvu/Am thuc/amthuc11.jpg', 'Địa chỉ: Đường Phó Cơ Điều, Phường 3, Thành phố Vĩnh Long, Vĩnh Long (nằm trong khu vực trung tâm sầm uất nhưng quán vẫn giữ được không gian thoải mái).\nThời gian mở cửa: Phục vụ chủ yếu từ trưa đến tối muộn, rất thích hợp cho các buổi họp mặt lai rai.\nQuán sở hữu không gian rộng rãi, thoáng mát và bình dân, mang lại cảm giác gần gũi, thoải mái cho thực khách ngay khi bước vào. Đây là địa điểm lý tưởng dành cho các buổi tụ tập bạn bè, liên hoan gia đình, đồng nghiệp hoặc những ai muốn tìm một nơi nhẹ nhàng để thưởng thức các món ăn ngon sau giờ làm việc.\nThực đơn của Mai Rừng Quán rất đa dạng, nổi bật với các món ăn được chế biến từ nguồn nguyên liệu tươi ngon của vùng đồng quê và đặc sản rừng núi:\nCác món ăn từ thịt gà, thịt heo rừng, ếch, lươn được biến tấu đa dạng qua các hình thức nướng lu, xào lăn, chiên mắm hay hấp hành, mang lại hương vị đậm đà, bắt mồi.\nThực đơn các món lẩu nóng hổi, thanh ngọt từ nước dùng kết hợp với các loại rau đồng nội đặc trưng của miền Tây, tạo nên điểm nhấn khó quên cho bữa ăn.\nQuán nhận được nhiều phản hồi tích cực từ khách hàng nhờ phong cách phục vụ bình dân, chu đáo, món ăn được chế biến nhanh và giá cả rất phải chăng, phù hợp với túi tiền của đa số thực khách tại địa phương.', 'Nhà hàng', 'https://www.google.com/maps/place/Mai+R%E1%BB%ABng+Qu%C3%A1n/@10.044618,106.5821164,17z/data=!3m1!4b1!4m6!3m5!1s0x319ff927c5537727:0x9e679bc56a469c2e!8m2!3d10.0446127!4d106.5846913', 1, '2026-06-15 09:48:06', '2026-06-16 09:36:21', 'approved', NULL),
(15, 1, 39, 'Quán Nhậu Tường San', 'qu-n-nh-u-t-ng-san', 'Kp An Bình, Tân Thủy, Bến Tre', '0977554527', '', '', 10.04461800, 106.58211640, 30000.00, 100000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc12.jpg', 'Địa chỉ: Nằm trên trục đường Nguyễn Văn Thiệt, Phường 3, Thành phố Vĩnh Long, Vĩnh Long.\nThời gian mở cửa: Phục vụ chủ yếu từ chiều tối cho đến đêm muộn.\nQuán sở hữu không gian mở, thiết kế theo phong cách bình dân, rộng rãi và vô cùng thoáng đãng. Điểm cộng lớn của quán là bầu không khí nhộn nhịp, thoải mái, rất thích hợp cho các buổi tụ tập bạn bè xem bóng đá, liên hoan gia đình, họp mặt đồng nghiệp sau những giờ làm việc căng thẳng.\nMenu tại Tường San rất phong phú với các món mồi bén, được chế biến từ nhiều nguồn nguyên liệu quen thuộc như hải sản, bò, heo, gà và các loại cá đồng:\nCác món nướng và xào lăn tại đây được nêm nếm đậm đà, dậy mùi thơm đặc trưng, rất thích hợp để dùng kèm với các loại đồ uống lạnh.\nCác món lẩu hải sản, lẩu thái hay lẩu xí quách với nước dùng ngọt thanh, đồ nhúng tươi ngon luôn là lựa chọn hàng đầu của thực khách để kết thúc bữa tiệc.\nQuán được lòng khách hàng địa phương nhờ tốc độ lên món khá nhanh, nhân viên phục vụ nhiệt tình và mức giá bình dân, hợp lý, phù hợp với túi tiền của đại đa số người lao động cũng như các bạn sinh viên.\n', 'Quán ăn', 'https://www.google.com/maps/search/Qu%C3%A1n+Nh%E1%BA%ADu+T%C6%B0%E1%BB%9Dng+San/@10.044618,106.5821164,17z', 1, '2026-06-15 09:48:07', '2026-06-16 09:36:21', 'approved', NULL),
(16, 1, 38, 'Bánh xèo Long Bình 2', 'b-nh-x-o-long-b-nh-2', 'Đường Đồng Khởi, Khóm 8, Trà Vinh', '0939946116', '', '', 9.91982080, 106.34318020, 40000.00, 120000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc13.jpg', 'Địa chỉ: Đường Quốc lộ 53, Ấp Long Bình, Xã Long Phước, Huyện Long Hồ, Vĩnh Long (nằm dọc theo tuyến đường lớn, khá dễ tìm đối với khách đi đường dài).\nThời gian mở cửa: Phục vụ chủ yếu từ trưa cho đến chiều tối.\nGiá cả: trung bình 50.000 - 100.000/món\nQuán sở hữu không gian rộng rãi, thoáng mát, mang phong cách bình dị và mộc mạc của vùng sông nước. Sảnh ăn được bố trí nhiều bàn ghế để phục vụ các đoàn khách du lịch lớn hoặc các gia đình tụ họp vào dịp cuối tuần. Khu vực đổ bánh xèo thường được đặt ở phía trước hoặc không gian mở, giúp thực khách có thể tận mắt quan sát quy trình tráng bánh khéo léo của người thợ.\nĐiểm làm nên thương hiệu của Bánh xèo Long Bình 2 chính là sự chăm chút trong từng chiếc bánh và nguyên liệu đi kèm:\nVỏ bánh được tráng mỏng, rìa bánh giòn rụm, có màu vàng ươm đẹp mắt từ nghệ và thơm béo mùi nước cốt dừa nhưng không hề bị ngấy dầu mỡ.\nPhần nhân bánh rất đầy đặn, đa dạng với các lựa chọn như tôm, thịt ba chỉ, tép đồng kết hợp cùng giá đỗ, đậu xanh nứt vỏ, hoặc củ hủ dừa, măng non tùy theo mùa để tạo độ ngọt tự nhiên.\nNước chấm và rau rừng chính là linh hồn của món ăn tại đây. Quán phục vụ một rổ rau vô cùng phong phú với hàng chục loại rau sống và rau rừng đặc trưng của miền Tây như lá cách, đọt xoài, cải xanh, xà lách, rau thơm. Nước mắm chua ngọt được pha chế vừa vị, có thêm đồ chua từ củ cải trắng và cà rốt bào sợi, kích thích vị giác của người ăn.\nQuán nhận được nhiều đánh giá tích cực nhờ chất lượng món ăn ổn định qua nhiều năm, tốc độ phục vụ nhanh nhẹn ngay cả khi đông khách và mức giá cả phải chăng, xứng đáng với chất lượng.', 'Quán ăn', 'https://www.google.com/maps/place/B%C3%A1nh+x%C3%A8o+Long+B%C3%ACnh+2/@9.9198261,106.3406053,17z/data=!3m1!4b1!4m6!3m5!1s0x31a01776355162af:0xf630a2147e7e214b!8m2!3d9.9198208!4d106.3431802', 0, '2026-06-15 09:48:07', '2026-06-16 09:36:21', 'approved', NULL),
(17, 1, 38, 'Bún Nem Nướng Thủy Triều', 'b-n-nem-n-ng-th-y-tri-u', '04 Phạm Ngũ Lão, Trà Vinh', '0949127368', '', '', 9.95058820, 106.34064670, 30000.00, 80000.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc14.jpg', 'Địa chỉ: Nằm trên đường Nguyễn Huệ, Phường 2, Thành phố Vĩnh Long, Vĩnh Long (khu vực gần chợ hoặc các trường học, rất thuận tiện cho việc di chuyển).\nThời gian mở cửa: Thường phục vụ từ sáng sớm cho đến chiều tối, thích hợp cho cả bữa sáng năng lượng hay bữa xế nhẹ nhàng.\nQuán được thiết kế theo phong cách bình dân, mộc mạc và luôn được dọn dẹp sạch sẽ. Không gian tuy không quá lớn nhưng cách bố trí bàn ghế gọn gàng, tạo cảm giác thoải mái cho thực khách khi ngồi thưởng thức tại chỗ. Ngoài ra, quán cũng có lượng khách mua mang về rất đông nhờ tốc độ chuẩn bị món nhanh chóng.\nSức hút của tô bún tại đây đến từ sự kết hợp hài hòa giữa các nguyên liệu tươi ngon được chuẩn bị trong ngày:\nNem nướng được làm từ thịt heo tươi, quết kỹ để đạt độ dai ngon tự nhiên, nêm nếm gia vị đậm đà rồi xiên que nướng trên bếp than hồng. Nem khi chín có màu vàng nâu bắt mắt, dậy mùi thơm phức, khi ăn cảm nhận được vị ngọt của thịt và không bị khô.\nMột tô bún đầy đủ thường bao gồm bún tươi, nem nướng cắt nhỏ, chả giò chiên giòn rụm, cùng với các loại rau sống xắt nhỏ như xà lách, rau thơm, dưa leo và đồ chua từ củ cải, cà rốt.\nNước chấm đi kèm là nước mắm chua ngọt được pha chế khéo léo theo khẩu vị miền Tây, có độ sánh nhẹ, thêm chút ớt băm cay nồng giúp kích thích vị giác và làm tăng thêm độ đậm đà cho món ăn.', 'Quán ăn', 'https://www.google.com/maps/place/B%C3%BAn+Nem+N%C6%B0%E1%BB%9Bng+Th%E1%BB%A7y+Tri%E1%BB%81u/@9.9505935,106.3380718,17z/data=!3m1!4b1!4m6!3m5!1s0x31a010a8abf10b7f:0x13d1c41845747dcf!8m2!3d9.9505882!4d106.3406467', 0, '2026-06-15 09:48:07', '2026-06-16 09:36:21', 'approved', NULL),
(18, 1, 38, 'Quán Nem Nướng Ngã Ba Đuôi Cá', 'quan-nem-nuong-nga-ba-duoi-ca', 'W8QJ+695, Võ Văn Kiệt, Nguyệt Hóa, Trà Vinh', '0944146685', '', '', 9.95322540, 106.34071980, 30000.00, 80000.00, '22:00:00', '21:00:00', '/images/Dichvu/Am thuc/amthuc15.jpg', 'Quán Nem Nướng Ngã Ba Đuôi Cá là một địa chỉ ẩm thực quen thuộc, đặc biệt nổi tiếng với những ai yêu thích món nem nướng truyền thống tại khu vực Trà Vinh (nằm giáp ranh và rất gần với Vĩnh Long).\nDưới đây là một số thông tin giới thiệu về quán:\nĐịa chỉ: 110 Phạm Ngũ Lão, Khóm 4, Phường 1, Thành phố Trà Vinh, Tỉnh Trà Vinh.\nThời gian mở cửa: 10:00 – 21:00 hàng ngày.\nSố điện thoại: +84 944 146 685\nQuán mang phong cách bình dân, mộc mạc và gần gũi. Không gian tuy không quá cầu kỳ nhưng đổi lại luôn sạch sẽ, bàn ghế sắp xếp gọn gàng, tạo cảm giác thoải mái cho thực khách khi ngồi ăn tại chỗ. Nhờ vị trí nằm gần khu vực ngã ba quen thuộc nên quán rất dễ tìm và là điểm dừng chân hợp lý cho cả người dân địa phương lẫn khách vãng lai.\nMón ăn làm nên tên tuổi của quán chính là mẹt nem nướng được chuẩn bị chỉn chu:\nNem nướng được chế biến theo công thức gia truyền, thịt heo được quết khéo léo để giữ độ dai ngon tự nhiên, nướng xèo xèo trên bếp than mang lại mùi thơm ngào ngạt và màu sắc vàng nâu bắt mắt. Khi ăn, nem có vị ngọt béo hài hòa, không bị khô.\nMột phần nem nướng đầy đủ sẽ đi kèm với bánh tráng cuốn, bún tươi, bánh tráng chiên giòn rụm và một rổ rau sống tươi xanh, đa dạng các loại rau thơm, dưa leo, khế chua hoặc chuối chát xắt mỏng.\nNước chấm tại đây được pha chế theo công thức riêng, có độ sánh mịn, vị béo thơm vừa vặn, kết hợp cùng chút ớt xay cay nồng làm tăng thêm hương vị đậm đà khi cuốn thịt và rau.\nQuán nhận được mức đánh giá khá tốt 4.1/5 sao trên hệ thống Google Maps nhờ chất lượng món ăn ổn định, hương vị vừa miệng và phong cách phục vụ nhanh nhẹn, thân thiện.', 'Quán ăn', NULL, 0, '2026-06-15 09:48:07', '2026-06-15 09:48:07', 'approved', NULL),
(19, 1, 38, 'Ngô Đồng Garden', 'ng-ng-garden', '43 Lê Lợi, Trà Vinh', '0939730799', '', '', 9.95322540, 106.34071980, 80000.00, 250000.00, '10:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc16.jpg', 'Địa chỉ: 43 Lê Lợi, Thành phố Trà Vinh (nằm ở khu vực trung tâm, rất thuận tiện cho thực khách di chuyển từ các vùng lân cận).\nThời gian mở cửa: 10:00 – 22:00 hàng ngày.\nSố điện thoại: +84 939 730 799\nKhông gian quán\nNgô Đồng Garden sở hữu không gian sân vườn rộng rãi, thoáng mát đúng như tên gọi của mình. Quán được thiết kế theo phong cách hiện đại, kết hợp hài hòa giữa cây xanh và các góc check-in lên hình cực lung linh. Đây là địa điểm rất thích hợp cho các buổi tiệc gia đình, họp mặt bạn bè, tổ chức sinh nhật, liên hoan hoặc cho các cặp đôi muốn tìm kiếm một không gian lãng mạn, thư thái vào buổi tối.\nẨm thực đặc trưng\nMenu của quán rất phong phú, phục vụ đầy đủ từ các món ăn gia đình, món nhậu lai rai cho đến các món nước và ăn vặt hiện đại:\nCác món ăn được chế biến từ hải sản tươi sống, thịt heo, gà, bò với cách nêm nếm đậm đà, trang trí bắt mắt, phù hợp với khẩu vị của thực khách mọi lứa tuổi.\nBên cạnh thực đơn món ăn, quán còn có menu đồ uống đa dạng, được pha chế chỉn chu để phục vụ khách hàng đến thư giãn, trò chuyện.\nQuán nhận được mức đánh giá cực kỳ cao 4.8/5 sao trên hệ thống Google Maps nhờ không gian đẹp, đồ ăn ngon, sạch sẽ và phong cách phục vụ chu đáo, nhiệt tình của đội ngũ nhân viên. Nếu bạn đang tìm kiếm một không gian sân vườn thoáng đãng để dùng bữa và chụp ảnh đẹp thì Ngô Đồng Garden là một lựa chọn không nên bỏ qua.', 'Quán ăn', 'https://www.google.com/maps/place/Qu%C3%A1n+Nem+N%C6%B0%E1%BB%9Bng+Ng%C3%A3+Ba+%C4%90u%C3%B4i+C%C3%A1/@9.9532307,106.3381449,17z/data=!3m1!4b1!4m6!3m5!1s0x31a010a67afb09a1:0x4b648ab8cc70f4eb!8m2!3d9.9532254!4d106.3407198', 0, '2026-06-15 09:48:07', '2026-06-15 09:48:07', 'approved', NULL),
(20, 1, 38, 'Quán Hồng Trúc', 'quan-hong-truc', 'Khóm 1, Hòa Thuận, Trà Vinh', '0908747828', '', '', 9.94258270, 106.34780430, 50000.00, 150000.00, '08:00:00', '21:00:00', '/images/Dichvu/Am thuc/amthuc17.jpg', 'Thông tin chung\nĐịa chỉ: Khóm 1, Hòa Thuận, Châu Thành, Trà Vinh\nThời gian mở cửa: 07:30 – 21:30 hàng ngày.\nSố điện thoại: +84 908 747 828\nQuán sở hữu không gian mở mang phong cách bình dân, mộc mạc và rất thoáng đãng. Với lối thiết kế rộng rãi, bàn ghế sắp xếp đơn giản nhưng sạch sẽ, nơi đây tạo cảm giác gần gũi và thoải mái cho thực khách. Đây là địa điểm rất thích hợp để tụ họp bạn bè lai rai, tổ chức các bữa ăn gia đình ấm cúng hoặc liên hoan nhỏ sau giờ làm việc.\nThực đơn của Quán khá phong phú, tập trung vào các món ăn đồng quê, hải sản bình dân và các món mồi nhậu bắt vị:\nCác món ăn được chế biến từ nguồn nguyên liệu tươi sống như gà, heo, ếch, lươn và các loại cá đồng, được nêm nếm đậm đà theo đúng khẩu vị miền Tây sông nước.\nCác món nướng, chiên mắm, xào lăn hay các loại lẩu nóng hổi với nước dùng thanh ngọt, ăn kèm rau sống tươi xanh luôn là lựa chọn yêu thích của thực khách khi đến quán.\nQuán nhận được mức đánh giá khá tốt 4.1/5 sao trên hệ thống Google Maps nhờ hương vị món ăn vừa miệng, tốc độ lên món nhanh nhẹn và mức giá cả bình dân, hợp lý với túi tiền của mọi đối tượng khách hàng.', 'Nhà hàng', 'https://www.google.com/maps/place/Qu%C3%A1n+H%E1%BB%93ng+Tr%C3%BAc/@9.942588,106.3452294,17z', 1, '2026-06-15 09:48:08', '2026-06-15 09:48:08', 'approved', NULL),
(23, 1, 30, 'Quán Hoa Bằng Lăng', 'quan-hoa-bang-lang', '136 Đường 30 Tháng 4, Long Đức, Trà Vinh', '0799422906', '', '', 9.95345890, 106.31861320, 20000.00, 60000.00, '08:00:00', '12:00:00', '/images/Dichvu/Am thuc/amthuc18.jpg', ' 136 Đường 30 Tháng 4, Long Đức, Thành phố Vĩnh Long, Vĩnh Long.\nThời gian mở cửa: Mở cửa cả ngày.\nSố điện thoại: +84 799 422 906\nKhông gian quán\nQuán sở hữu phong cách mộc mạc, gần gũi và thoáng đãng nhờ vị trí nằm trên trục đường lớn. Thiết kế không gian mang lại cảm giác thoải mái, dễ chịu, không quá cầu kỳ nhưng lại rất ấm cúng. Nơi đây phù hợp cho nhiều nhu cầu khác nhau của thực khách, từ việc ngồi nhâm nhi ly cà phê sáng đọc báo, gặp gỡ đối tác công việc, cho đến những buổi tối tụ họp tán gẫu cùng gia đình và bạn bè dưới ánh đèn lung linh.\nThực đơn đồ uống\nMenu của quán tập trung vào các dòng thức uống truyền thống và hiện đại, đáp ứng tốt khẩu vị của nhiều lứa tuổi:\nCác món cà phê mang hương vị đậm đà, đặc trưng như cà phê đen đá, cà phê sữa đá pha phin truyền thống hoặc các dòng cà phê pha máy thơm nhẹ.\nBên cạnh cà phê, quán còn phục vụ đa dạng các loại trà trái cây nhiệt đới thanh mát, sinh tố, nước ép nguyên chất bổ dưỡng và các dòng trà sữa béo ngậy đi kèm nhiều loại topping cho giới trẻ.\nQuán nhận được phản hồi rất tích cực từ thực khách nhờ chất lượng đồ uống ổn định, giá cả bình dân, hợp lý cùng phong cách phục vụ thân thiện, chu đáo và nhanh nhẹn của đội ngũ nhân viên.', 'Nhà hàng', 'https://www.google.com/maps/place/Qu%C3%A1n+Hoa+B%E1%BA%B1ng+L%C4%83ng/@9.9534642,106.3160383,17z', 2, '2026-06-15 09:48:09', '2026-07-05 23:35:08', 'approved', NULL),
(37, 3, 30, 'Khu Du Lịch Huỳnh Kha', 'khu-du-lich-huynh-kha', 'Chu Văn An, Xóm Long Bình, Long Đức, Vĩnh Long, Việt Nam', '02946282828', NULL, NULL, 9.95685950, 106.34643350, 0.00, 0.00, '08:00:00', '22:00:00', '/images/Diemthamquan/Diemthamquan1.jpg', 'Tọa lạc tại khu phố Long Bình, Phường 4, Thành phố Trà Vinh, Khu du lịch sinh thái Huỳnh Kha là một tổ hợp vui chơi, giải trí và ẩm thực có quy mô lớn, được đầu tư hiện đại. Nơi đây sở hữu khuôn viên rộng rãi với thảm thực vật xanh mướt, những hồ nước nhân tạo uốn lượn và hệ thống tiểu cảnh được chăm chút kỹ lưỡng. Đối với người dân địa phương và du khách, Huỳnh Kha như một \"lá phổi xanh\" ngay lòng thành phố, nơi lý tưởng để trốn khỏi sự ồn ào, tất bật của cuộc sống thường nhật.', NULL, 'https://www.google.com/maps/place/Khu+Du+L%E1%BB%8Bch+Hu%E1%BB%B3nh+Kha/@9.9568648,106.3438586,17z/data=!3m1!4b1!4m6!3m5!1s0x31a01bf295720ac3:0x92e8d1ff5d420a3c!8m2!3d9.9568595!4d106.3464335', 1, NULL, '2026-07-06 04:04:49', 'approved', NULL),
(38, 3, 28, 'Khu Du Lịch Cộng Đồng Cồn Chim', 'con-chim', 'Road, Hòa Minh, Vĩnh Long, Việt Nam', '0355732342', NULL, NULL, 9.92027120, 106.42325570, 50000.00, 100000.00, '07:00:00', '18:00:00', '/images/Diemthamquan/Diemthamquan2.jpg', 'Nằm giữa dòng sông Cổ Chiên thơ mộng thuộc xã Hòa Minh, huyện Châu Thành, Cồn Chim là một điểm sáng nổi bật của mô hình du lịch \"thuận thiên\" – tức là làm du lịch dựa vào tự nhiên, bảo vệ môi trường và giữ gìn văn hóa bản địa. Điểm đặc biệt nhất của Cồn Chim là người dân sống theo quy luật một mùa ngọt, một mùa mặn. Vào mùa nước ngọt, họ trồng lúa sạch không hóa chất; vào mùa nước mặn, họ nuôi tôm, cua tự nhiên.', NULL, 'https://www.google.com/maps/place/Khu+Du+L%E1%BB%8Bch+C%E1%BB%99ng+%C4%90%E1%BB%93ng+C%E1%BB%93n+Chim/@9.9202765,106.4206808,17z/data=!3m1!4b1!4m6!3m5!1s0x31a019f554e864c1:0x71e074844a0759bf!8m2!3d9.9202712!4d106.4232557', 1, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(39, 3, 26, 'Di Tích Ao Bà Om', 'ao-ba-om', '68 Nguyễn Du, khóm 3, Nguyệt Hóa, Vĩnh Long, Việt Nam', NULL, NULL, NULL, 9.91809470, 106.30416150, 0.00, 0.00, '06:00:00', '18:00:00', '/images/Diemthamquan/Diemthamquan3.jpg', 'Ao Bà Om, còn được gọi là Ao Vuông, là một thắng cảnh danh tiếng bậc nhất và là niềm tự hào của người dân Trà Vinh. Nằm tại khóm 3, phường 8, thành phố Trà Vinh, di tích này là một hồ nước phẳng lặng, trong xanh, có hình dáng gần như một hình vuông hoàn hảo. Bao bọc xung quanh ao là những gò cát nhấp nhô với hàng trăm cây sao, cây dầu cổ thụ hàng trăm năm tuổi. Những bộ rễ cây khổng lồ, trồi lên khỏi mặt đất, uốn lượn thành vô số hình thù kỳ dị, độc đáo, tạo nên một không gian vô cùng huyền bí và cổ kính.', NULL, 'https://www.google.com/maps/place/Di+T%C3%ADch+Ao+B%C3%A0+Om/@9.9177076,106.3014906,17z/data=!4m10!1m2!2m1!1zRGkgVMOtY2ggQW8gQsOgIE9t!3m6!1s0x31a0170030507f83:0x44487e4f53103976!8m2!3d9.9180947!4d106.3041615', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(40, 3, 26, 'Chùa Khmer chùa Âng', 'chua-ang', 'QL53, khóm 13, Nguyệt Hóa, Vĩnh Long, Việt Nam', NULL, NULL, NULL, 9.91569340, 106.30358420, 0.00, 0.00, '06:00:00', '18:00:00', '/images/Diemthamquan/Diemthamquan4.jpg', 'Nằm ngay sát cạnh thắng cảnh Ao Bà Om, Chùa Âng (tên đầy đủ là Wat Angkor Raigore Rangsey) là một trong những ngôi chùa cổ kính, độc đáo và có kiến trúc đẹp nhất trong hệ thống hơn 140 ngôi chùa Khmer tại Trà Vinh. Được xây dựng từ nhiều thế kỷ trước, Chùa Âng mang đậm dấu ấn kiến trúc Angkor cổ điển của người Khmer, kết hợp hài hòa với cảnh quan thiên nhiên của những hàng cây cổ thụ xung quanh.', NULL, 'https://www.google.com/maps/place/Ch%C3%B9a+Khmer+ch%C3%B9a+%C3%82ng/@9.9156987,106.3010093,17z/data=!3m1!4b1!4m6!3m5!1s0x31a0171e96d21c49:0x6dd641af069fdf6b!8m2!3d9.9156934!4d106.3035842', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(41, 3, 29, 'KDL sinh thái Làng Xanh Bến Tre', 'lang-xanh-ben-tre', '111D, ĐT883, An Phú Thạnh, Phú Túc, Vĩnh Long 930000, Việt Nam', '0948008289', NULL, NULL, 10.31515150, 106.31462350, 80000.00, 200000.00, '08:00:00', '17:00:00', '/images/Diemthamquan/Diemthamquan5.jpg', 'Tọa lạc tại huyện Châu Thành, tỉnh Bến Tre, Khu du lịch sinh thái Làng Xanh là một điểm đến vui chơi giải trí mang đậm hơi thở đồng quê Nam Bộ nhưng được quy hoạch rất bài bản và hiện đại. Với diện tích rộng lớn, không gian nơi đây ngập tràn sắc xanh của những vườn dừa, ao sen và cây ăn trái mát mẻ. Đây là địa điểm được các hội nhóm, công ty và gia đình cực kỳ yêu thích để tổ chức các hoạt động dã ngoại, team building tràn ngập tiếng cười.', NULL, 'https://www.google.com/maps/place/KDL+sinh+th%C3%A1i+L%C3%A0ng+Xanh+B%E1%BA%BFn+Tre/@10.3151568,106.3120486,17z/data=!3m1!4b1!4m6!3m5!1s0x310aa5d8c156bb53:0x99a2e1ffb9b7aa21!8m2!3d10.3151515!4d106.3146235', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(42, 3, 25, 'Bảo Tàng Tỉnh Bến Tre', 'bao-tang-ben-tre', '69MF+XMF, Hùng Vương, An Hội, Vĩnh Long, Việt Nam', '02753822735', NULL, NULL, 10.23493950, 106.37415710, 20000.00, 40000.00, '07:30:00', '16:30:00', '/images/Diemthamquan/Diemthamquan6.jpg', 'Nằm bên bờ sông Bến Tre thơ mộng thuộc trung tâm thành phố, Bảo tàng tỉnh Bến Tre là một công trình kiến trúc mang đậm phong cách Pháp cổ kính, trang nhã. Ngôi nhà này ban đầu là dinh thự của các viên chức thời Pháp thuộc, sau đó được sử dụng làm nơi trưng bày, lưu giữ các giá trị lịch sử, văn hóa của quê hương xứ dừa. Khuôn viên bảo tàng rộng rãi, rợp bóng mát của những cây cổ thụ và trưng bày nhiều hiện vật thể khối lớn như máy bay, pháo binh quân sự.', NULL, 'https://www.google.com/maps/place/B%E1%BA%A3o+Ta%CC%80ng+Ti%CC%89nh+B%E1%BA%BFn+Tre/@10.2349448,106.3715822,17z/data=!3m1!4b1!4m6!3m5!1s0x310aa85c3fc00d0f:0x1107cf4ce5f17a01!8m2!3d10.2349395!4d106.3741571', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(43, 3, 29, 'Di tích Đạo Dừa', 'dao-dua', 'ấp Tân Vinh, Phú Túc, Vĩnh Long, Việt Nam', NULL, NULL, NULL, 10.33609740, 106.36928220, 0.00, 0.00, '07:00:00', '17:00:00', '/images/Diemthamquan/Diemthamquan7.jpg', 'Di tích Đạo Dừa nằm trong khuôn viên của Khu du lịch Cồn Phụng, thuộc xã Tân Thạch, huyện Châu Thành, tỉnh Bến Tre. Đây là nơi lưu giữ những dấu tích kiến trúc độc đáo gắn liền với cuộc đời của ông Nguyễn Thành Nam (1910 - 1990), người đã sáng lập ra giáo phái Đạo Dừa (hòa đồng các tôn giáo và chủ trương mang lại hòa bình) vào giữa thế kỷ 20. Khu di tích này mang một màu sắc văn hóa - tôn giáo vô cùng kỳ lạ và độc đáo.', NULL, 'https://www.google.com/maps/place/Di+t%C3%ADch+%C4%90%E1%BA%A1o+D%E1%BB%ABa/@10.3361027,106.3667073,17z/data=!3m1!4b1!4m6!3m5!1s0x310aaf98856d53b3:0x19cb5085ec80b587!8m2!3d10.3360974!4d106.3692822', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(44, 3, 4, 'Văn Thánh Miếu Vĩnh Long', 'van-thanh-mieu', 'Làng Long Hồ, Trần Phú, thành phố Vĩnh Long, Vĩnh Long, Việt Nam', NULL, NULL, NULL, 10.24266230, 105.98435890, 0.00, 0.00, '07:00:00', '17:00:00', '/images/Diemthamquan/Diemthamquan8.jpg', 'Nằm bên bờ sông Long Hồ thơ mộng thuộc phường 4, thành phố Vĩnh Long, Văn Thánh Miếu Vĩnh Long là một trong ba Văn Thánh Miếu được xây dựng đầu tiên ở vùng đất Nam Kỳ (cùng với Biên Hòa và Gia Định). Được khởi công xây dựng vào thế kỷ 19 dưới sự đề xướng của quan Kinh lược sứ Phan Thanh Giản và Đốc học Nguyễn Thông, công trình này được ví như \"Quốc Tử Giám của miền Tây\".', NULL, 'https://www.google.com/maps/place/V%C4%83n+Tha%CC%81nh+Mi%C3%AA%CC%81u+v%C4%A9nh+long/@10.2426676,105.981784,17z/data=!3m1!4b1!4m6!3m5!1s0x310a9d39a9d6c89d:0x9012f6966d03aba7!8m2!3d10.2426623!4d105.9843589', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(45, 3, 12, 'Đền Thờ Phạm Hùng', 'den-pham-hung', 'ấp Long Thuận A, Long Hồ, Vĩnh Long, Việt Nam', '02703834286', NULL, NULL, 10.22436050, 105.98906810, 0.00, 0.00, '07:00:00', '17:00:00', '/images/Diemthamquan/Diemthamquan9.jpg', 'Đền thờ Chủ tịch Hội đồng Bộ trưởng Phạm Hùng tọa lạc tại xã Long Phước, huyện Long Hồ, tỉnh Vĩnh Long, ngay bên dòng sông Long Hồ êm đềm. Đây là công trình văn hóa – lịch sử có ý nghĩa vô cùng to lớn, được xây dựng để tưởng nhớ và tri ân những công lao vĩ đại của đồng chí Phạm Hùng – một người con ưu tú của quê hương Vĩnh Long, một nhà lãnh đạo kiên trung, xuất sắc của Đảng và Cách mạng Việt Nam.', NULL, 'https://www.google.com/maps/search/%C4%90%E1%BB%81n+Th%E1%BB%9D+Ph%E1%BA%A1m+H%C3%B9ng/@10.2426676,105.981784,17z', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(46, 3, 18, 'Điểm du lịch lò gạch vườn táo Phước Lợi', 'lo-gach-phuoc-loi', '63C8+CQ7, Nhơn Phú, Vĩnh Long, Việt Nam', '0902205045', NULL, NULL, 10.22104210, 106.06691110, 30000.00, 80000.00, '08:00:00', '17:00:00', '/images/Diemthamquan/Diemthamquan10.jpg', 'Nằm tại khu vực Mang Thít, Vĩnh Long – nơi được mệnh danh là \"vương quốc lò gạch\" của miền Tây, Điểm du lịch lò gạch vườn táo Phước Lợi là một mô hình tham quan mới lạ, kết hợp độc đáo giữa di sản làng nghề truyền thống và du lịch sinh thái miệt vườn. Đến đây, bạn sẽ bị choáng ngợp bởi khung cảnh những lò gạch nung rêu phong có kiến trúc tựa như những tòa tháp cổ rực rỡ sắc cam dưới ánh nắng mặt trời.', NULL, 'https://www.google.com/maps/place/%C4%90i%E1%BB%83m+du+l%E1%BB%8Bch+l%C3%B2+g%E1%BA%A1ch+v%C6%B0%E1%BB%9Dn+t%C3%A1o+Ph%C6%B0%E1%BB%9Bc+L%E1%BB%A3i/@10.2210474,106.0643362,17z', 0, NULL, '2026-06-16 09:36:21', 'approved', NULL),
(58, 2, 26, 'GO! Trà Vinh', 'go-tra-vinh', '414 Võ Nguyên Giáp, Nguyệt Hóa, Trà Vinh', '0778708129', NULL, NULL, 9.92325870, 106.32853310, 0.00, 0.00, '08:00:00', '22:00:00', '/images/Dichvu/Mua sam/muasam1.jpg', 'GO! Trà Vinh là trung tâm thương mại hiện đại quy mô lớn, tích hợp mua sắm, ăn uống, vui chơi giải trí đáp ứng nhu cầu mọi lứa tuổi.', NULL, 'https://www.google.com/maps/place/GO!+Tr%C3%A0+Vinh/@9.923264,106.3259582,17z', 0, NULL, NULL, 'approved', NULL),
(59, 2, 26, 'Siêu thị Co.opmart Trà Vinh', 'coopmart-tra-vinh', 'Đ. Nguyễn Đáng, Khóm 9, Trà Vinh', '0886500707', NULL, NULL, 9.92406490, 106.34052700, 0.00, 0.00, '07:00:00', '21:30:00', '/images/Dichvu/Mua sam/muasam2.jpg', 'Co.opmart Trà Vinh là điểm mua sắm thân quen gắn với đời sống hàng ngày của người dân. Hàng hóa đa dạng, chất lượng đảm bảo an toàn vệ sinh thực phẩm.', NULL, 'https://www.google.com/maps/search/Si%C3%AAu+th%E1%BB%8B+Co.opmart+Tr%C3%A0+Vinh/@9.923264,106.3259582,17z', 2, NULL, NULL, 'approved', NULL),
(60, 2, 26, 'Vincom Plaza Trà Vinh', 'vincom-plaza-tra-vinh', '24 Nguyễn Thị Minh Khai, Trà Vinh', '0947051636', NULL, NULL, 9.93595730, 106.33691900, 0.00, 0.00, '09:30:00', '21:30:00', '/images/Dichvu/Mua sam/muasam3.jpg', 'Vincom Plaza Trà Vinh là biểu tượng mua sắm hiện đại, quy tụ thương hiệu thời trang, mỹ phẩm, khu ẩm thực và rạp chiếu phim.', NULL, 'https://www.google.com/maps/search/Vincom+Plaza+Tr%C3%A0+Vinh/@9.9240702,106.3379521,17z', 0, NULL, NULL, 'approved', NULL),
(61, 2, 25, 'Trung tâm thương mại SENSE CITY', 'sense-city-ben-tre', '26A Trần Quốc Tuấn, An Hội, Bến Tre', '02753833999', NULL, NULL, 10.24134810, 106.37653380, 0.00, 0.00, '08:30:00', '22:00:00', '/images/Dichvu/Mua sam/muasam4.jpg', 'Sense City Bến Tre là trung tâm thương mại giải trí quy mô lớn, kết hợp mua sắm, ẩm thực, rạp phim và khu vui chơi trẻ em.', NULL, 'https://www.google.com/maps/search/Trung+t%C3%A2m+th%C6%B0%C6%A1ng+m%E1%BA%A1i+SENSE+CITY/@9.9359626,106.3343441,17z', 0, NULL, NULL, 'approved', NULL),
(62, 2, 24, 'Siêu thị Điện máy XANH', 'dien-may-xanh-tra-vinh', 'Ấp Sa Bình, Long Đức, Trà Vinh', '1900232461', NULL, NULL, 9.95853510, 106.33979030, 500000.00, 50000000.00, '07:30:00', '20:30:00', '/images/Dichvu/Mua sam/muasam5.jpg', 'Điện máy Xanh chuyên phân phối tivi, tủ lạnh, máy giặt, điện thoại. Chính sách bảo hành rõ ràng, giao hàng lắp đặt tận nơi.', NULL, 'https://www.google.com/maps/search/Si%C3%AAu+th%E1%BB%8B+%C4%90i%E1%BB%87n+m%C3%A1y+XANH/@10.4323793,105.9240268,10z', 0, NULL, NULL, 'approved', NULL),
(63, 2, 26, 'WinMart Vincom Trà Vinh', 'winmart-vincom-tra-vinh', 'TTTM VinCom Plaza, Phường 2, Trà Vinh', '0559701593', NULL, NULL, 9.93592500, 106.33648000, 0.00, 0.00, '08:00:00', '22:00:00', '/images/Dichvu/Mua sam/muasam6.jpg', 'WinMart tại Vincom Plaza cung cấp thực phẩm tươi sống, nông sản an toàn và đồ gia dụng. Không gian sạch sẽ, thanh toán nhanh chóng.', NULL, 'https://www.google.com/maps/search/WinMart+Vincom+Tr%C3%A0+Vinh/@10.4323793,105.9240268,10z', 0, NULL, NULL, 'approved', NULL),
(64, 2, 27, 'Siêu Thị Dừa Bến Tre', 'sieu-thi-dua-ben-tre', 'SHP1.06 Nguyễn Thị Định, Phú Tân, Bến Tre', '0907328728', NULL, NULL, 10.25668830, 106.37860180, 0.00, 0.00, '08:00:00', '17:00:00', '/images/Dichvu/Mua sam/muasam7.jpg', 'Siêu Thị Dừa chuyên đặc sản từ cây dừa Bến Tre: kẹo dừa, bánh phồng, dầu dừa, mỹ phẩm thiên nhiên và đồ thủ công mỹ nghệ.', NULL, 'https://www.google.com/maps/place/Si%C3%AAu+Th%E1%BB%8B+D%E1%BB%ABa+B%E1%BA%BFn+Tre/@10.2566936,106.3760269,17z', 0, NULL, NULL, 'approved', NULL),
(65, 2, 25, 'Siêu thị điện máy nội thất Chợ Lớn', 'dien-may-cho-lon-ben-tre', '171D Võ Nguyên Giáp, Bến Tre', '02753835868', NULL, NULL, 10.24242310, 106.34823810, 500000.00, 50000000.00, '08:30:00', '21:30:00', '/images/Dichvu/Mua sam/muasam8.jpg', 'Điện máy nội thất Chợ Lớn Bến Tre chuyên điện tử, điện lạnh, đồ gia dụng và nội thất cao cấp. Thường xuyên ưu đãi trả góp linh hoạt.', NULL, 'https://www.google.com/maps/place/Si%C3%AAu+thi%CC%A3+%C4%91i%C3%AA%CC%A3n+ma%CC%81y+n%C3%B4%CC%A3i+th%C3%A2%CC%81t+Ch%C6%A1%CC%A3+L%C6%A1%CC%81n/@10.2424284,106.3456632,17z', 0, NULL, NULL, 'approved', NULL),
(66, 2, 25, 'DreamKids Bến Tre', 'dreamkids-ben-tre', 'Sense City, An Hội, Bến Tre', '02753838833', NULL, NULL, 10.24187010, 106.37673810, 50000.00, 200000.00, '09:00:00', '21:30:00', '/images/Dichvu/Mua sam/muasam9.jpg', 'DreamKids là khu vui chơi trong nhà quy mô lớn cho trẻ em tại Bến Tre. Nhà phao, nhà bóng, cầu trượt và các góc chơi giáo dục sáng tạo.', NULL, 'https://www.google.com/maps/place/DreamKids+B%E1%BA%BFn+Tre/@10.2418754,106.3741632,17z', 0, NULL, NULL, 'approved', NULL),
(67, 2, 27, 'Trung Tâm Mua Sắm Điện Máy Nguyễn Kim Bến Tre', 'nguyen-kim-ben-tre', '336 A1 Đại lộ Đồng Khởi, Phú Tân, Bến Tre', '02757306768', NULL, NULL, 10.25406530, 106.37059110, 500000.00, 50000000.00, '08:00:00', '22:00:00', '/images/Dichvu/Mua sam/muasam10.jpg', 'Nguyễn Kim Bến Tre là trung tâm bán lẻ điện máy uy tín tại Đại lộ Đồng Khởi. Đa dạng sản phẩm, dịch vụ trả góp và bảo hành chuyên nghiệp.', NULL, 'https://www.google.com/maps/place/Trung+T%C3%A2m+Mua+S%E1%BA%AFm+%C4%90i%E1%BB%87n+M%C3%A1y+Nguy%E1%BB%85n+Kim+B%E1%BA%BFn+Tre/@10.2540706,106.3680162,17z', 0, NULL, NULL, 'approved', NULL),
(68, 1, 38, 'T-Cup_Drink & Food', 't-cup-drink-food', '10.016 khu vực Trà Vinh', '(0270) 000 0000', NULL, NULL, 10.01615950, 106.40250940, 20000.00, 60000.00, '07:00:00', '22:00:00', '/images/Dichvu/Am thuc/amthuc19.jpg', 'T-Cup Drink & Food là chuỗi đồ uống và ăn nhẹ hiện đại, phục vụ các loại trà, cà phê, smoothie và các món ăn nhẹ thơm ngon. Không gian trẻ trung, phù hợp cho giới trẻ.', 'Café', 'https://www.google.com/maps/place/T-Cup_Drink+%26+Food/@10.0161648,106.3999345,17z', 0, NULL, NULL, 'approved', NULL),
(69, 1, 38, 'Cà phê 30 tháng tư', 'ca-phe-30-thang-tu', 'Khu vực Trà Vinh', '(0270) 000 0000', NULL, NULL, 10.01616480, 106.39993450, 25000.00, 70000.00, '06:00:00', '23:00:00', '/images/Dichvu/Am thuc/amthuc20.jpg', 'Cà phê 30 tháng tư là điểm hẹn cà phê quen thuộc của người dân địa phương. Không gian thoáng mát, thức uống đa dạng từ cà phê truyền thống đến các loại nước ép tươi.', 'Café', 'https://www.google.com/maps/search/C%C3%A0+ph%C3%AA+30+th%C3%A1ng+t%C6%B0/@10.0161648,106.3999345,17z', 0, NULL, NULL, 'approved', NULL),
(86, 1, 1, 'Nhà hàng hải sản Hùng Biển Seafood', 'nh-h-ng-h-i-s-n-h-ng-bi-n-seafood', '294 Trần Phú Nối Dài, Nguyệt Hóa, Vĩnh Long, Việt Nam', '', '', '', NULL, NULL, 200000.00, 300000.00, '09:00:00', '23:00:00', '/images/Dichvu/Am thuc/1783387734_40258.jpg', 'Chào mừng mọi người đã đến với Hùng Biển Seafood – không gian ẩm thực hải sản tươi sống hàng đầu tại Trà Vinh!\nLà những người tâm huyết với ẩm thực biển, chúng tôi luôn mong muốn mang đến cho thực khách những trải nghiệm tuyệt vời nhất ngay tại mảnh đất Trà Vinh thân thương. Dưới đây là những điều mà Hùng Biển Seafood tự hào cam kết với mọi khách hàng:\nHải sản bao tươi, chất lượng bao ngon: Toàn bộ hải sản từ tôm, cua, ghẹ, mực đến các loại cá, ốc... đều được tuyển chọn kỹ lưỡng, giữ độ tươi sống trong bể kính và chỉ chế biến khi khách gọi món. Dù là hấp xả thanh ngọt, nướng mọi thơm lừng, hay sốt trứng muối, rang muối hồng đậm đà... đầu bếp bên em đều chăm chút từng đĩa một.\nKhông gian rộng rãi, thoáng mát: Quán sở hữu mặt bằng rộng, thiết kế thoáng đãng, lộng gió, cực kỳ lý tưởng cho những buổi tụ họp gia đình, lai rai cùng bạn bè, hay tổ chức tiệc liên hoan, sinh nhật, họp mặt công ty.\nPhục vụ tận tình như người nhà: Đội ngũ nhân viên trẻ trung, nhiệt tình của quán luôn sẵn sàng hỗ trợ, lên món nhanh nhẹn để cuộc vui của anh chị không bị gián đoạn.\nGiá cả bình dân, hợp lý: Ăn ngon, hải sản chất lượng nhưng giá cả cực kỳ phải chăng, rõ ràng, giúp anh chị thoải mái ăn uống mà không lo về giá.', NULL, NULL, 0, '2026-07-07 00:06:20', '2026-07-07 02:15:48', 'approved', 'nhat1234'),
(87, 1, 1, 'Bún nước lèo Muời Lượng', 'b-n-n-c-l-o-mu-i-l-ng', '443 Hoàng Sa, Xuân Hòa, Hồ Chí Minh, Việt Nam', '', '', '', NULL, NULL, 20000.00, 100000.00, '14:00:00', '20:00:00', '/images/Dichvu/Am thuc/1783387710_28936.jpg', 'Chào mừng mọi người đã ghé thăm Bún nước lèo Mười Lượng!\nQuán chúng tôi luôn tự hào gìn giữ và mang đến cho thực khách tô bún nước lèo chuẩn vị miền Tây. Nước lèo tại quán luôn giữ được độ trong, vị ngọt thanh tự nhiên, đậm đà mà không hề bị gắt.\nBún nước lèo Mười Lượng sẽ đánh thức mọi giác quan của bạn với đầy đủ các nguyên liệu tươi ngon: cá lóc đồng ngọt thịt, tôm đất luộc lột vỏ dai thơm, và không thể thiếu những miếng thịt quay giòn rụm và da béo ngậy.\nRau sống tươi xanh, sạch sẽ: quán chuẩn bị sẵn mẹt rau sống tươi rói gồm bông súng chẻ, bắp chuối bào, giá đỗ và rau thơm. Thêm một chút ớt bằm, một vắt chanh tươi là đúng điệu.\nQuán luôn chú trọng khâu vệ sinh an toàn thực phẩm. Không gian quán thoáng mát, sạch sẽ, cùng với sự tiếp đón niềm nở, nhanh nhẹn, chúng tôi mong muốn mỗi thực khách đến đây đều cảm thấy thoải mái như đang ăn cơm nhà.', NULL, NULL, 1, '2026-07-07 00:10:50', '2026-07-07 02:15:46', 'approved', 'nhat1234');
INSERT INTO `locations` (`id`, `category_id`, `district_id`, `name`, `slug`, `address`, `phone`, `facebook_url`, `zalo_url`, `lat`, `lng`, `min_price`, `max_price`, `opening_time`, `closing_time`, `featured_image`, `description`, `type`, `google_map_url`, `view_count`, `created_at`, `updated_at`, `status`, `submitted_by`) VALUES
(88, 3, 1, 'Cây Dầu cổ thụ Trà Vinh', 'c-y-d-u-c-th-tr-vinh', 'W89J+54H, Nguyệt Hóa, Vĩnh Long, Việt Nam', '', '', '', NULL, NULL, 0.00, 0.00, '08:00:00', '22:00:00', '/images/Dichvu/Am thuc/1783390501_39116.jpg', '1', NULL, NULL, 0, '2026-07-07 02:15:01', '2026-07-07 02:15:45', 'approved', 'nhat1234');

