--
-- Cấu trúc bảng cho bảng `location_reviews`
--

CREATE TABLE `location_reviews` (
  `id` int(10) UNSIGNED NOT NULL,
  `location_id` int(10) UNSIGNED NOT NULL,
  `user_id` varchar(100) NOT NULL,
  `user_name` varchar(150) NOT NULL DEFAULT 'Người dùng',
  `rating` tinyint(3) UNSIGNED NOT NULL DEFAULT 5,
  `comment` text DEFAULT NULL,
  `image_path` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Đang đổ dữ liệu cho bảng `location_reviews`
--

INSERT INTO `location_reviews` (`id`, `location_id`, `user_id`, `user_name`, `rating`, `comment`, `image_path`, `created_at`, `updated_at`) VALUES
(1, 6, '8', 'Nhat User', 5, 'các món ăn rất ngon', '', '2026-07-03 06:52:08', '2026-07-03 06:52:08'),
(261, 16, '8', 'Nhat User', 5, 'bánh xèo rất ngon', '/images/reviews/1783218580_5516.webp', '2026-07-05 09:29:40', '2026-07-05 09:29:40'),
