(452, 69, 'user_5', 'Hoàng Văn Em', 3, 'Ăn ổn, nhưng chưa có gì quá đặc sắc so với các quán khác.', NULL, '2026-04-16 09:49:49', '2026-07-05 09:49:49'),
(453, 69, 'user_2', 'Trần Thị Bình', 5, 'Thức ăn ngon, tươi và đậm đà. Nhân viên phục vụ nhiệt tình.', NULL, '2025-12-29 09:49:49', '2026-07-05 09:49:49'),
(454, 69, 'user_4', 'Phạm Thị Dung', 5, 'Món ăn tuyệt vời, đặc biệt là các món đặc sản miền Tây. Sẽ quay lại!', NULL, '2026-03-05 09:49:49', '2026-07-05 09:49:49'),
(455, 69, 'user_6', 'Vũ Thị Phương', 5, 'Thức ăn ngon, tươi và đậm đà. Nhân viên phục vụ nhiệt tình.', NULL, '2025-12-19 09:49:49', '2026-07-05 09:49:49'),
(456, 79, 'user_6', 'Vũ Thị Phương', 3, 'Ăn ổn, nhưng chưa có gì quá đặc sắc so với các quán khác.', NULL, '2026-04-21 09:49:49', '2026-07-05 09:49:49'),
(457, 79, 'user_9', 'Ngô Văn Tài', 4, 'Quán đông nhưng phục vụ nhanh, đồ ăn chất lượng.', NULL, '2026-04-28 09:49:49', '2026-07-05 09:49:49'),
(458, 79, 'user_4', 'Phạm Thị Dung', 3, 'Món ăn bình thường, nhưng giá cả phù hợp với chất lượng.', NULL, '2026-05-04 09:49:49', '2026-07-05 09:49:49'),
(459, 79, 'user_1', 'Nguyễn Văn An', 3, 'Ăn ổn, nhưng chưa có gì quá đặc sắc so với các quán khác.', NULL, '2026-02-25 09:49:49', '2026-07-05 09:49:49'),
(460, 79, 'user_3', 'Lê Minh Châu', 4, 'Thức ăn tươi ngon, giá vừa phải. Sẽ ghé lại lần sau.', NULL, '2026-03-21 09:49:49', '2026-07-05 09:49:49'),
(461, 79, 'user_2', 'Trần Thị Bình', 4, 'Quán đông nhưng phục vụ nhanh, đồ ăn chất lượng.', NULL, '2026-03-07 09:49:49', '2026-07-05 09:49:49'),
(462, 2, '8', 'Nhat User', 5, 'Mì cay ngon, nhân viên tận tình, không khí sinh động, nhìn muốn ăn liền,….menu đa dạng món ăn, phù hợp túi tiền.,, Sẽ ghé ủng suốt đời, suốt kiếp.', '', '2026-07-05 13:18:23', '2026-07-05 13:18:23'),
(463, 23, '8', 'Nhat User', 5, 'Ăn dịp lễ nên hơi đông, nhà mình đi 4 người lớn, do gà là ai gọi mới làm gà nên hơi lâu lên món nên mình có gọi 3 món ăn dặm trước là mì xào, ếch chiên nước mắm và gỏi xoài khô lóc.\nGỏi xoài là lúc gọi mới thấy mấy ac ra cây xoài hái xuống làm gỏi, nên cảm giác rất tươi mới, gỏi trộn vừa vị và nước mắm ngon.\nMì thì vị cũng tạm ko xuất sắc lắm, nhưng mực và tôm thì tươi và giòn\nẾch vị vừa ăn và thịt tươi dai, chắc cũng vừa xuống hồ bắt lên làm 😄\nVà món best seller phải nhắc tới là gà, gà tre thịt chắc dai vừa, luộc lên ngọt thịt đúng chuẩn gà vườn. Cháo theo mình thấy thì tạm thôi. Được thịt gà là điểm nhấn và khách đến gọi thì quán mới làm.\nKhông gian cạnh bờ sông gió lồng lộng mát mẻ.\nTiếp theo là giá, bao nhiêu đó món no ứ hự mà bill chỉ có 590, free trà đá 😳 thiệt sự quá rẻ luôn. So với các quán sân vườn thì đúng là vừa rẻ vừa ngon vừa chill.\nMình đánh giá công tâm để các bạn đến ăn và trải nghiệm, đừng nhìn mấy đánh giá tào lao, khen cũng đánh giá 1 sao tội quán.\nAi ghé TV nên đến thử nha 🥰', '', '2026-07-05 13:41:03', '2026-07-05 13:41:03');

